using System.Collections;using CoordinateLoadOption;using UnityEngine;using System.Text.Json;
int passed=0,failed=0;var results=new List<object>();
void Check(bool ok,string reason){if(!ok)throw new Exception(reason);}
void Test(string name,Action action){try{action();passed++;results.Add(new{name,passed=true});}catch(Exception e){failed++;results.Add(new{name,passed=false,error=e.GetType().Name+": "+e.Message});}}
(MaterialEditor editor,GameObject go,ChaControl source,ChaControl target) Setup(int kind,bool removing,string[] values){var source=new ChaControl();var target=new ChaControl();var e=new MaterialEditor{SourceChaCtrl=source,TargetChaCtrl=target};var go=new GameObject();go.Materials.Add(new Material{name="valid"});go.Renderers.Add(new Renderer{name="valid"});var key=MaterialEditor.storedValueInfos[kind].listName;var list=(ArrayList)(removing?e.TargetBackup:e.SourceBackup)[key];foreach(string value in values)list.Add(new SavedProperty{MaterialName=value,RendererName=value});if(removing){var live=(ArrayList)((SyntheticController)e.TargetController).Lists[key];foreach(var row in list)live.Add(row);}e.BackupWrites=0;CharaCustomFunctionController_Support.Logger.Warnings.Clear();return(e,go,source,target);}
void Run((MaterialEditor editor,GameObject go,ChaControl source,ChaControl target) x,bool remove){if(remove)x.editor.RemoveMaterialEditorData(x.target,0,x.go,MaterialEditor.ObjectType.Clothing);else x.editor.SetMaterialEditorData(x.source,0,x.target,0,x.go,MaterialEditor.ObjectType.Clothing);}
foreach(bool remove in new[]{false,true})foreach(int kind in new[]{1,2})foreach(var names in new[]{new[]{"valid","missing"},new[]{"missing","valid"},new[]{"missing","missing"},new[]{"valid","valid"},Array.Empty<string>()}){
 var values=names;string label=(remove?"remove":"set")+"/"+(kind==1?"renderer":"material")+"/"+string.Join(",",values);
 Test(label,()=>{var x=Setup(kind,remove,values);Run(x,remove);int good=values.Count(n=>n=="valid");var controller=(SyntheticController)x.editor.TargetController;Check(controller.Writes==good,"API call count changed");Check(x.editor.BackupWrites==(good>0?1:0),"backup refresh must aggregate successful records");Check(x.editor.TextureSnapshotReads==(good>0?1:0),"texture snapshot refresh lost");if(!remove)Check(CharaCustomFunctionController_Support.Logger.Warnings.Count==values.Length-good,"missing diagnostics hidden");var key=MaterialEditor.storedValueInfos[kind].listName;int current=((ArrayList)controller.Lists[key]).Count;Check(((ArrayList)x.editor.TargetBackup[key]).Count==current,"target backup stale");});
}
foreach(bool remove in new[]{false,true})Test((remove?"remove":"set")+" exception escaping reflection boundary still propagates",()=>{var x=Setup(2,remove,new[]{"valid","missing"});((SyntheticController)x.editor.TargetController).ThrowNext=true;bool thrown=false;try{Run(x,remove);}catch(InvalidOperationException){thrown=true;}Check(thrown&&x.editor.BackupWrites==0,"escaping boundary failure swallowed");});
foreach(bool remove in new[]{false,true})Test((remove?"remove":"set")+" unrelated slot and coordinate excluded",()=>{var x=Setup(2,remove,new[]{"valid"});var key=MaterialEditor.storedValueInfos[2].listName;var backup=remove?x.editor.TargetBackup:x.editor.SourceBackup;((ArrayList)backup[key]).Add(new SavedProperty{Slot=7});((ArrayList)backup[key]).Add(new SavedProperty{CoordinateIndex=2});Run(x,remove);Check(((SyntheticController)x.editor.TargetController).Writes==1,"unrelated saved entries touched");});
foreach(bool remove in new[]{false,true})foreach(int kind in new[]{0,3,4})Test((remove?"remove":"set")+" mixed shader/color/texture class "+kind,()=>{var x=Setup(kind,remove,new[]{"valid","missing"});if(kind==4&&!remove){var row=(SavedProperty)((ArrayList)x.editor.SourceBackup["MaterialTexturePropertyList"])[0];row.OffsetOriginal=1;row.Offset=2;}Run(x,remove);Check(((SyntheticController)x.editor.TargetController).Writes==1,"unexpected target call count");Check(x.editor.BackupWrites==1&&x.editor.TextureSnapshotReads==1,"class lost successful mutation");});
Test("texture record with no data or offset or scale makes no success claim",()=>{var x=Setup(4,false,new[]{"valid"});Run(x,false);Check(((SyntheticController)x.editor.TargetController).Writes==0&&x.editor.BackupWrites==0,"no-op marked successful");});
foreach(bool remove in new[]{false,true})Test((remove?"remove":"set")+" wrapper logged-error and null-return semantics preserved",()=>{var x=Setup(2,remove,new[]{"valid"});var controller=(SyntheticController)x.editor.TargetController;controller.ThrowNext=true;controller.WrapFailure=true;Run(x,remove);Check(controller.WrapperErrors==1&&controller.Writes==0&&x.editor.BackupWrites==1,"wrapper null return policy changed");});
Console.WriteLine(JsonSerializer.Serialize(new{passed,failed,checks=passed+failed,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
